using System;using System.Collections.Generic;using UnityEngine;using UnityEngine.UI;using TMPro;
// Editable scene UI sources. Only presentation is copied; values, text and callbacks stay live.
[DefaultExecutionOrder(30000)]public sealed class GridShiftUILayout:MonoBehaviour {
 [Serializable]public sealed class View {public string runtimeCanvas;public Canvas source;}
 public View[] views=Array.Empty<View>();static uint revision;uint seen=uint.MaxValue;int warmFrames=6;readonly HashSet<int> applied=new HashSet<int>();
 public static void Notify(){revision++;}
 void Awake(){if(!Application.isPlaying)return;foreach(var view in views)if(view.source!=null){view.source.enabled=false;view.source.gameObject.SetActive(false);foreach(var ray in view.source.GetComponentsInChildren<GraphicRaycaster>(true))ray.enabled=false;}}
 void LateUpdate(){if(!Application.isPlaying||warmFrames--<=0&&seen==revision)return;seen=revision;foreach(var view in views)if(view.source!=null&&view.source.gameObject.activeSelf)view.source.gameObject.SetActive(false);var live=UnityEngine.Object.FindObjectsByType<Canvas>(FindObjectsInactive.Include,FindObjectsSortMode.None);foreach(var view in views){if(view.source==null)continue;foreach(var canvas in live){if(canvas==null||canvas.name!=view.runtimeCanvas||canvas.GetComponentInParent<GridShiftUILayout>()!=null)continue;ApplyTree(view.source.transform,canvas.transform);}}}
 static string Key(Transform node){var binding=node.GetComponent<GridShiftUIElementBinding>();return binding!=null?binding.originalName:node.name;}
 void ApplyTree(Transform source,Transform target){if(applied.Add(target.GetInstanceID())){var s=source as RectTransform;var t=target as RectTransform;if(s!=null&&t!=null){t.anchorMin=s.anchorMin;t.anchorMax=s.anchorMax;t.pivot=s.pivot;t.sizeDelta=s.sizeDelta;t.anchoredPosition3D=s.anchoredPosition3D;t.localRotation=s.localRotation;t.localScale=s.localScale;}var image=source.GetComponent<Image>();var realImage=target.GetComponent<Image>();if(image!=null&&realImage!=null){realImage.sprite=image.sprite;realImage.color=image.color;realImage.type=image.type;realImage.preserveAspect=image.preserveAspect;}var text=source.GetComponent<TMP_Text>();var realText=target.GetComponent<TMP_Text>();if(text!=null&&realText!=null){realText.font=text.font;realText.fontSize=text.fontSize;realText.color=text.color;realText.fontStyle=text.fontStyle;realText.alignment=text.alignment;}var layout=source.GetComponent<HorizontalOrVerticalLayoutGroup>();var realLayout=target.GetComponent<HorizontalOrVerticalLayoutGroup>();if(layout!=null&&realLayout!=null){realLayout.padding=new RectOffset(layout.padding.left,layout.padding.right,layout.padding.top,layout.padding.bottom);realLayout.spacing=layout.spacing;realLayout.childAlignment=layout.childAlignment;realLayout.childControlHeight=layout.childControlHeight;realLayout.childControlWidth=layout.childControlWidth;realLayout.childForceExpandHeight=layout.childForceExpandHeight;realLayout.childForceExpandWidth=layout.childForceExpandWidth;}}
 for(int i=0;i<source.childCount;i++){var child=source.GetChild(i);int occurrence=0;for(int j=0;j<i;j++)if(Key(source.GetChild(j))==Key(child))occurrence++;Transform matched=null;for(int j=0;j<target.childCount;j++)if(target.GetChild(j).name==Key(child)&&occurrence--==0){matched=target.GetChild(j);break;}if(matched!=null)ApplyTree(child,matched);}}
}
